INSERT INTO public.client VALUES (50, 2, 'Μαρία Παπαδοπούλου', 'maria.papadopoulou@maildrop.cc', '+30 694 512 3387', '1990-04-12', 'Απώλεια βάρους 8-10 κιλών και σταθεροποίηση', 'Καθιστική εργασία (λογίστρια). Ιστορικό γιο-γιο διαιτών. Δυσανεξία στη λακτόζη — αποφυγή φρέσκου γάλακτος, ανέχεται γιαούρτι και σκληρά τυριά.', '2026-08-16 16:16:03.48129+00', '2026-08-16 16:16:03.48129+00', 0);
INSERT INTO public.client VALUES (51, 2, 'Γιώργος Αντωνίου', 'g.antoniou@maildrop.cc', '+30 697 884 2210', '1985-09-03', 'Αύξηση μυϊκής μάζας με ελεγχόμενο λίπος', 'Προπόνηση με αντιστάσεις 4x/εβδομάδα. Εργάζεται σε βάρδιες — τα γεύματα μετακινούνται συχνά.', '2026-08-16 16:16:03.508244+00', '2026-08-16 16:16:03.508245+00', 0);
INSERT INTO public.client VALUES (52, 2, 'Ελένη Δημητρίου', 'eleni.dimitriou@maildrop.cc', '+30 693 220 7741', '1998-01-27', 'Διατροφική υποστήριξη για ημιμαραθώνιο Νοεμβρίου', 'Τρέχει 55-70 χλμ/εβδομάδα. Ιστορικό χαμηλής φερριτίνης (2025) — παρακολούθηση.', '2026-08-16 16:16:03.535913+00', '2026-08-16 16:16:03.535913+00', 0);
INSERT INTO public.client VALUES (53, 2, 'Νίκος Καραγιάννης', 'n.karagiannis@maildrop.cc', '+30 698 331 5502', '1972-11-15', 'Γλυκαιμικός έλεγχος και απώλεια βάρους', 'Σακχαρώδης διαβήτης τύπου 2, υπό μετφορμίνη. Παρακολούθηση από ενδοκρινολόγο. HbA1c 7.4% στην έναρξη.', '2026-08-16 16:16:03.563367+00', '2026-08-16 16:16:03.563384+00', 0);
