INSERT INTO public.client VALUES (56, 2, 'Άννα Στεφανίδου', 'anna.stefanidou@maildrop.cc', '+30 695 776 3324', '1993-08-19', 'Διατροφή στην εγκυμοσύνη — 2ο τρίμηνο', 'Εγκυμοσύνη, 22η εβδομάδα. Πρωινή ναυτία υποχώρησε τον 4ο μήνα. Συμπλήρωμα φυλλικού και σιδήρου από τη μαία.', '2026-08-16 16:16:03.641508+00', '2026-08-16 16:16:03.641509+00', 0);
