INSERT INTO public.food_suggestion VALUES (4, 24, 2, NULL, 66.00, 10.20, NULL, NULL, 'Οι τιμές του καταλόγου φαίνεται να αφορούν στραγγιστό 4%. Για το 2% της αγοράς, οι ετικέτες τριών εμπορικών σημάτων συγκλίνουν στα 66 kcal και 10.2 g πρωτεΐνης ανά 100 g.', 'PENDING', '2026-08-16 16:15:17.298908+00', NULL);
INSERT INTO public.journal_entry VALUES (112, 2, 50, '2026-01-10', 'Πρώτη συνεδρία — λήψη ιστορικού', 'Λήψη διατροφικού ιστορικού και ανακλήσεως 24ώρου. Παραλείπει συστηματικά το πρωινό και τρώει το κύριο γεύμα μετά τις 22:00. Κατανάλωση αναψυκτικών περίπου 1L/ημέρα.
INSERT INTO public.journal_entry VALUES (113, 2, 50, '2026-03-07', 'Επανεκτίμηση 2 μηνών', 'Απώλεια 3.3 κιλών σε δύο μήνες — εντός του επιθυμητού ρυθμού. Το πρωινό έχει εδραιωθεί. Τα αναψυκτικά έχουν μειωθεί σε 2-3/εβδομάδα.
INSERT INTO public.journal_entry VALUES (114, 2, 50, '2026-05-02', 'Πλατό και προσαρμογή', 'Ο ρυθμός απώλειας επιβραδύνθηκε, όπως αναμενόταν. Αύξηση πρωτεΐνης στα 1.6 g/kg και προσθήκη περπατήματος 30 λεπτών x4/εβδομάδα.
INSERT INTO public.journal_entry VALUES (115, 2, 50, '2026-06-27', 'Τηλεφωνική επικοινωνία', 'Σύντομη επικοινωνία μετά από διακοπές. Διατήρησε το βάρος της κατά τη διάρκεια δεκαήμερης απουσίας — σημαντική ένδειξη ότι οι συνήθειες έχουν εδραιωθεί και δεν εξαρτώνται από το πλάνο.', '2026-08-16 16:16:05.696116+00', NULL, 0);
INSERT INTO public.journal_entry VALUES (116, 2, 50, '2026-08-08', 'Μετάβαση σε φάση συντήρησης', 'Συνολική απώλεια 8.5 κιλά. Η περιφέρεια μέσης μειώθηκε κατά 11.5 εκ. Ξεκινά σταδιακή αύξηση θερμίδων κατά 150 kcal/εβδομάδα προς τη συντήρηση.
INSERT INTO public.journal_entry VALUES (117, 2, 51, '2026-03-14', 'Έναρξη — αξιολόγηση προπονητικού φορτίου', 'Προπόνηση με αντιστάσεις 4 φορές/εβδομάδα, πρόγραμμα άνω/κάτω. Η πρόσληψη πρωτεΐνης εκτιμάται στα 1.1 g/kg — ανεπαρκής για τον στόχο.
INSERT INTO public.journal_entry VALUES (118, 2, 51, '2026-05-09', 'Έλεγχος 8 εβδομάδων', 'Αύξηση 2.9 κιλών με μείωση ποσοστού λίπους — η αναλογία κέρδους είναι ευνοϊκή. Η μυϊκή μάζα αυξήθηκε 2.5 κιλά.
INSERT INTO public.journal_entry VALUES (119, 2, 51, '2026-08-01', 'Ολοκλήρωση φάσης όγκου', 'Συνολική αύξηση 6.3 κιλά σε 4.5 μήνες, με το ποσοστό λίπους να έχει μειωθεί από 14.8% σε 13.6%. Εξαιρετικό αποτέλεσμα.
INSERT INTO public.journal_entry VALUES (120, 2, 52, '2026-04-18', 'Αρχική αξιολόγηση δρομέα', 'Εβδομαδιαίος όγκος 55-70 χλμ. Η πρόσληψη υδατανθράκων είναι χαμηλή για το φορτίο (περίπου 3.8 g/kg). Ιστορικό χαμηλής φερριτίνης το 2025.
INSERT INTO public.journal_entry VALUES (121, 2, 52, '2026-06-13', 'Αποτελέσματα εξετάσεων και περιοδισμός', 'Φερριτίνη 34 ng/mL — χαμηλή αλλά εντός ορίων. Ενισχύθηκαν οι διατροφικές πηγές σιδήρου με ταυτόχρονη πρόσληψη βιταμίνης C.
INSERT INTO public.journal_entry VALUES (122, 2, 52, '2026-08-08', 'Δοκιμή στρατηγικής αγώνα', 'Δοκιμάστηκε το πρωτόκολλο τροφοδοσίας σε διαδρομή 18 χλμ: 60 g υδατανθράκων/ώρα. Καλή ανοχή, χωρίς γαστρεντερικά συμπτώματα.
INSERT INTO public.journal_entry VALUES (123, 2, 53, '2026-01-24', 'Πρώτη συνεδρία — παραπομπή ενδοκρινολόγου', 'ΣΔ τύπου 2 υπό μετφορμίνη 1000mg x2. HbA1c 7.4%. Παραπομπή για διατροφική παρέμβαση.
INSERT INTO public.journal_entry VALUES (124, 2, 53, '2026-03-21', 'Έλεγχος 2 μηνών', 'Απώλεια 3.5 κιλών. Η γλυκόζη νηστείας έχει πέσει στα 118-130 mg/dL. Ο ίδιος αναφέρει σημαντικά λιγότερη μεταγευματική υπνηλία.
INSERT INTO public.journal_entry VALUES (125, 2, 53, '2026-05-16', 'Επανάληψη HbA1c', 'HbA1c 6.8% — μείωση 0.6 μονάδων. Ο ενδοκρινολόγος διατηρεί την ίδια δοσολογία και θα επανεκτιμήσει στους έξι μήνες.
INSERT INTO public.journal_entry VALUES (126, 2, 53, '2026-08-08', 'Σταθεροποίηση', 'HbA1c 6.4%. Συνολική απώλεια 10.1 κιλά και 12.5 εκ. στη μέση. Το σπλαχνικό λίπος από επίπεδο 16 σε 12.
INSERT INTO public.journal_entry VALUES (127, 2, 54, '2026-05-23', 'Αρχική εκτίμηση χορτοφαγικής διατροφής', 'Ωβογαλακτοχορτοφάγος από διετίας. Η πρόσληψη πρωτεΐνης υπολογίζεται στα 0.9 g/kg — χαμηλή. Ο σίδηρος και η B12 χρήζουν προσοχής.
INSERT INTO public.journal_entry VALUES (128, 2, 54, '2026-07-18', 'Πρόοδος', 'Η πρωτεΐνη έχει ανέβει στα 1.3 g/kg μέσω οσπρίων, γιαουρτιού και αυγών. Η μυϊκή μάζα αυξήθηκε κατά 0.9 κιλά.
INSERT INTO public.journal_entry VALUES (129, 2, 55, '2026-02-28', 'Έναρξη — καρδιαγγειακό προφίλ', 'LDL 168 mg/dL, HDL 41, τριγλυκερίδια 190. Ο καρδιολόγος ζήτησε τρίμηνη διατροφική παρέμβαση πριν εξεταστεί στατίνη.
INSERT INTO public.journal_entry VALUES (130, 2, 55, '2026-07-04', 'Επανάληψη λιπιδαιμικού', 'LDL 132 mg/dL — μείωση 36 μονάδων. Τριγλυκερίδια 148. Ο καρδιολόγος ανέβαλε τη φαρμακευτική αγωγή για άλλους τρεις μήνες.
INSERT INTO public.journal_entry VALUES (131, 2, 56, '2026-04-04', 'Πρώτη συνεδρία — 15η εβδομάδα κύησης', 'Η ναυτία του πρώτου τριμήνου έχει υποχωρήσει. Βάρος προ κύησης 59 κιλά, ΔΜΣ 20.9 — φυσιολογικός.
INSERT INTO public.journal_entry VALUES (132, 2, 56, '2026-06-13', '22η εβδομάδα', 'Αύξηση 3.9 κιλών από την έναρξη — εντός του αναμενόμενου εύρους για το δεύτερο τρίμηνο.
INSERT INTO public.journal_entry VALUES (133, 2, 56, '2026-08-15', '31η εβδομάδα', 'Συνολική αύξηση 7.8 κιλά. Ρυθμός φυσιολογικός. Αναφέρει καούρα το βράδυ — συστάθηκαν μικρότερα και συχνότερα γεύματα και αποφυγή κατάκλισης για δύο ώρες μετά το φαγητό.
