INSERT INTO public.plan VALUES (45, 2, 51, 'Πλάνο αύξησης μυϊκής μάζας', 'ISSUED', 3100.00, 145.00, 372.00, 86.00, 'MIFFLIN_ST_JEOR', 1.725, 'Τα δύο γεύματα γύρω από την προπόνηση δεν μετακινούνται. Στη νυχτερινή βάρδια, το πρωινό γίνεται το γεύμα των 15:00 και η σειρά διατηρείται.', '2026-08-16 16:16:10.031027+00', '2026-08-16 16:16:11.802749+00', 54);
INSERT INTO public.plan VALUES (49, 2, 55, 'Καρδιοπροστατευτικό πλάνο', 'ISSUED', 1950.00, 117.00, 195.00, 76.00, 'MIFFLIN_ST_JEOR', 1.375, 'Ψάρι τουλάχιστον δύο φορές την εβδομάδα, όσπρια τρεις. Κόκκινο κρέας έως μία φορά. Χωρίς αλλαντικά. Το ελαιόλαδο παραμένει, ωμό κατά προτίμηση.', '2026-08-16 16:16:15.503537+00', '2026-08-16 16:16:16.817394+00', 41);
INSERT INTO public.plan VALUES (48, 2, 54, 'Χορτοφαγικό πλάνο — προσχέδιο', 'DRAFT', 2050.00, 82.00, 267.00, 68.00, 'MIFFLIN_ST_JEOR', 1.550, 'Προσχέδιο — εκκρεμεί ο έλεγχος επάρκειας σιδήρου και ψευδαργύρου πριν δοθεί στην πελάτισσα.', '2026-08-16 16:16:14.943318+00', '2026-08-16 16:16:15.477813+00', 17);
INSERT INTO public.plan VALUES (50, 2, 56, 'Πλάνο 2ου τριμήνου', 'ISSUED', 2300.00, 98.00, 288.00, 80.00, 'MIFFLIN_ST_JEOR', 1.375, 'Χωρίς ωμό ψάρι, μη παστεριωμένα τυριά και αλλαντικά. Η φέτα να είναι από παστεριωμένο γάλα. Μικρότερα και συχνότερα γεύματα λόγω καούρας — το βραδινό έως τις 20:30.', '2026-08-16 16:16:16.844504+00', '2026-08-16 16:16:18.321238+00', 47);
INSERT INTO public.plan VALUES (43, 2, 50, 'Πλάνο απώλειας βάρους — Μάιος', 'ISSUED', 1650.00, 124.00, 165.00, 55.00, 'MIFFLIN_ST_JEOR', 1.375, 'Το βραδινό να ολοκληρώνεται έως τις 21:00. Ελαιόλαδο έως 3 κουταλιές την ημέρα συνολικά, συμπεριλαμβανομένου του μαγειρέματος. Νερό τουλάχιστον 2 λίτρα.', '2026-08-16 16:16:06.113224+00', '2026-08-16 16:16:08.945584+00', 84);
INSERT INTO public.plan VALUES (44, 2, 50, 'Πλάνο έναρξης — Ιανουάριος', 'ARCHIVED', 1800.00, 108.00, 202.00, 60.00, 'MIFFLIN_ST_JEOR', 1.200, 'Αντικαταστάθηκε από το πλάνο Μαΐου. Διατηρείται ως μέρος του ιστορικού.', '2026-08-16 16:16:08.972197+00', '2026-08-16 16:16:10.005291+00', 32);
INSERT INTO public.plan VALUES (47, 2, 53, 'Πλάνο γλυκαιμικού ελέγχου', 'ISSUED', 1900.00, 133.00, 171.00, 74.00, 'MIFFLIN_ST_JEOR', 1.375, 'Οι υδατάνθρακες κατανέμονται σε τρία γεύματα και δεν συγκεντρώνονται στο βραδινό. Μέτρηση γλυκόζης νηστείας κάθε πρωί και δύο ώρες μετά το κύριο γεύμα δύο φορές την εβδομάδα.', '2026-08-16 16:16:12.336892+00', '2026-08-16 16:16:14.916634+00', 77);
INSERT INTO public.plan VALUES (46, 2, 52, 'Ημέρα μεγάλης διαδρομής', 'ISSUED', 2650.00, 92.00, 397.00, 74.00, 'HARRIS_BENEDICT', 1.900, 'Ισχύει για τις ημέρες με διαδρομή άνω των 15 χλμ. Τροφοδοσία εν κινήσει 60 g υδατανθράκων/ώρα, επιπλέον του πλάνου. Σίδηρος με πηγή βιταμίνης C στο ίδιο γεύμα.', '2026-08-16 16:16:11.830304+00', '2026-08-16 16:16:12.313448+00', 16);
